var i=`architecture-decision-records-adr`;var o=110;var n={en:[{id:`T110-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Architecture Decision Records (ADR)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Conway's Law observes that system designs tend to reflect the communication structures of the organizations creating them.`},{id:`B`,text:`An ADR records an architectural choice, the context that motivated it, alternatives, consequences and status.`},{id:`C`,text:`The Theory of Constraints holds that overall throughput is limited by a small number of bottlenecks.`},{id:`D`,text:`System design is the deliberate choice among imperfect alternatives under explicit requirements.`}]},{id:`T110-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Architecture Decision Records (ADR)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Write short decision records near the code, including assumptions, constraints, decision drivers, rejected options and review triggers.`},{id:`B`,text:`Rank performance bottlenecks, incident sources, customer complaints or feature adoption using real data.`},{id:`C`,text:`Estimate upfront effort, ongoing operations, avoided incidents, delivery acceleration and opportunity cost.`},{id:`D`,text:`Estimate coordination paths, module separability and onboarding capacity before scaling a team.`}]},{id:`T110-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`Architecture Decision Records (ADR)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A team choosing a modular monolith over microservices may accept a shared deployment in exchange for simpler transactions and lower operations cost. It can define growth signals for reconsideration.`},{id:`B`,text:`Replacing a manual invoice export with automation may cost two weeks initially but save several hours weekly and reduce errors. Factor in support, edge cases and reliability of the automation.`},{id:`C`,text:`If frontend and backend groups work in silos, product features may suffer API handoffs. A small cross-functional team owning reservations end-to-end can reduce those coordination costs.`},{id:`D`,text:`A team documents why it chose a modular monolith and PostgreSQL for reservations, accepting shared deployment in exchange for simpler transactions and team operations.`}]},{id:`T110-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Architecture Decision Records (ADR)`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Bottlenecks shift under different workloads.`},{id:`B`,text:`Rare events can be catastrophic despite low volume; security and compliance cannot be prioritized by frequency alone.`},{id:`C`,text:`Buying is not zero engineering; vendor contracts, outages and migrations are part of the system.`},{id:`D`,text:`An ADR should not be a lengthy design specification or a way to rubber-stamp decisions after implementation.`}]},{id:`T110-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It preserves decision history so teams can revisit trade-offs rather than repeat debates.`}]}]},{id:`T110-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`An ADR should silently overwrite old decisions so no history remains.`}]}]},{id:`T110-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Without ownership and review triggers, decisions become obsolete and untrusted.`}]}]},{id:`T110-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Architecture Decision Records (ADR)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Write short decision records near the code, including assumptions, constraints, decision drivers, rejected options and review triggers.`},{id:`B`,text:`Decision records should omit rejected alternatives and review triggers.`},{id:`C`,text:`An ADR records an architectural choice, the context that motivated it, alternatives, consequences and status.`},{id:`D`,text:`Improving any non-bottleneck stage always increases end-to-end throughput.`}]},{id:`T110-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Architecture Decision Records (ADR)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A team documents why it chose a modular monolith and PostgreSQL for reservations, accepting shared deployment in exchange for simpler transactions and team operations.`},{id:`B`,text:`Every metric and defect category must follow an exact 80/20 distribution.`},{id:`C`,text:`Without ownership and review triggers, decisions become obsolete and untrusted.`},{id:`D`,text:`An ADR should silently overwrite old decisions so no history remains.`}]},{id:`T110-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A team documents why it chose a modular monolith and PostgreSQL for reservations, accepting shared deployment in exchange for simpler transactions and team operations.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to analyze incident and latency data, chart cumulative impact, recommend top fixes and separately flag low-frequency high-severity risks.`},{id:`B`,text:`Ask an agent to create a build/buy matrix for authentication, email and booking rules, with vendor exit plans and three-year total-cost ranges.`},{id:`C`,text:`Ask an agent to map throughput across an import pipeline, identify the bottleneck from measurements and propose staged improvements with before/after flow metrics.`},{id:`D`,text:`Ask an agent to draft an ADR comparing event-driven and synchronous booking workflows, then have it list evidence that would overturn the selected option.`}]},{id:`T110-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What new evidence would justify superseding this ADR in six months?`}]}]},{id:`T110-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A team documents why it chose a modular monolith and PostgreSQL for reservations, accepting shared deployment in exchange for simpler transactions and team operations.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Architecture Decision Records (ADR)`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T110-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A team documents why it chose a modular monolith and PostgreSQL for reservations, accepting shared deployment in exchange for simpler transactions and team operations.`,b:!0},{t:` — propose three checks for `},{t:`Architecture Decision Records (ADR)`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T110-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A team documents why it chose a modular monolith and PostgreSQL for reservations, accepting shared deployment in exchange for simpler transactions and team operations.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T110-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Architecture Decision Records (ADR)`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A team documents why it chose a modular monolith and PostgreSQL for reservations, accepting shared deployment in exchange for simpler transactions and team operations.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T110-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Записи архітектурних рішень (ADR)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Закон Конвея описує тенденцію систем відображати комунікаційну структуру організацій, які їх створюють.`},{id:`B`,text:`ADR фіксує архітектурний вибір, його контекст, альтернативи, наслідки та стан.`},{id:`C`,text:`Теорія обмежень стверджує, що загальну пропускну здатність обмежує невелика кількість вузьких місць.`},{id:`D`,text:`Системне проєктування — свідомий вибір між недосконалими альтернативами за конкретних вимог.`}]},{id:`T110-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Записи архітектурних рішень (ADR)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Пишіть короткі записи поруч із кодом: припущення, обмеження, критерії, відхилені альтернативи й умови перегляду.`},{id:`B`,text:`Ранжуйте вузькі місця, причини інцидентів, скарги чи використання фіч за даними.`},{id:`C`,text:`Оцініть стартову працю, експлуатаційні витрати, уникнені інциденти, прискорення релізів і альтернативну вартість.`},{id:`D`,text:`Перш ніж збільшувати команду, оцініть канали координації, незалежність модулів і можливість онбордингу.`}]},{id:`T110-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Записи архітектурних рішень (ADR)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Команда може обрати модульний моноліт замість мікросервісів, погодившись на спільний реліз заради простіших транзакцій і менших витрат. При цьому зафіксувати сигнали для перегляду рішення.`},{id:`B`,text:`Автоматизація ручного експорту рахунків може коштувати два тижні розробки, але щотижня економити години й зменшувати помилки. Врахуйте підтримку, винятки й надійність процесу.`},{id:`C`,text:`Якщо frontend і backend працюють ізольовано, фічі гальмують на передачі API. Невелика кросфункціональна команда, що відповідає за бронювання наскрізно, зменшує витрати координації.`},{id:`D`,text:`Команда записує, чому обрала модульний моноліт і PostgreSQL для бронювань, погодившись на спільне розгортання заради простіших транзакцій і підтримки.`}]},{id:`T110-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Записи архітектурних рішень (ADR)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Вузькі місця змінюються за різного навантаження.`},{id:`B`,text:`Рідкісні події можуть бути катастрофічними; безпеку й відповідність вимогам не можна оцінювати лише частотою.`},{id:`C`,text:`Купівля не означає нуль інженерної роботи: контракти, збої постачальника й міграції стають частиною системи.`},{id:`D`,text:`ADR не має бути багатосторінковою специфікацією чи формальністю після реалізації.`}]},{id:`T110-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Він зберігає історію, щоб команди могли переоцінювати компроміси, а не повторювати суперечки.`}]}]},{id:`T110-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`ADR має непомітно переписувати старі рішення, щоб не залишалося історії.`}]}]},{id:`T110-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Без відповідального та умов перегляду він швидко застаріває.`}]}]},{id:`T110-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Записи архітектурних рішень (ADR)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Пишіть короткі записи поруч із кодом: припущення, обмеження, критерії, відхилені альтернативи й умови перегляду.`},{id:`B`,text:`Записи рішень мають пропускати відхилені альтернативи й умови перегляду.`},{id:`C`,text:`ADR фіксує архітектурний вибір, його контекст, альтернативи, наслідки та стан.`},{id:`D`,text:`Прискорення будь-якого етапу, що не є вузьким місцем, завжди збільшує пропускну здатність.`}]},{id:`T110-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Записи архітектурних рішень (ADR)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Команда записує, чому обрала модульний моноліт і PostgreSQL для бронювань, погодившись на спільне розгортання заради простіших транзакцій і підтримки.`},{id:`B`,text:`Кожна метрика й категорія дефектів мусить мати точний розподіл 80/20.`},{id:`C`,text:`Без відповідального та умов перегляду він швидко застаріває.`},{id:`D`,text:`ADR має непомітно переписувати старі рішення, щоб не залишалося історії.`}]},{id:`T110-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Команда записує, чому обрала модульний моноліт і PostgreSQL для бронювань, погодившись на спільне розгортання заради простіших транзакцій і підтримки.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента проаналізувати інциденти й затримки, побудувати накопичений вплив, запропонувати головні виправлення та окремо позначити рідкісні критичні ризики.`},{id:`B`,text:`Попросіть агента скласти матрицю build/buy для входу, пошти та правил бронювання з планом виходу від постачальника й трирічною оцінкою витрат.`},{id:`C`,text:`Попросіть агента зіставити пропускну здатність етапів імпорту, знайти вузьке місце за вимірами й запропонувати поетапні покращення з порівнянням результату.`},{id:`D`,text:`Попросіть агента підготувати ADR про синхронний чи подієвий процес бронювання та перелічити докази для перегляду вибору.`}]},{id:`T110-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які нові факти стануть підставою замінити цей ADR через пів року?`}]}]},{id:`T110-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Команда записує, чому обрала модульний моноліт і PostgreSQL для бронювань, погодившись на спільне розгортання заради простіших транзакцій і підтримки.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Записи архітектурних рішень (ADR)`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T110-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Команда записує, чому обрала модульний моноліт і PostgreSQL для бронювань, погодившись на спільне розгортання заради простіших транзакцій і підтримки.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Записи архітектурних рішень (ADR)`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T110-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Команда записує, чому обрала модульний моноліт і PostgreSQL для бронювань, погодившись на спільне розгортання заради простіших транзакцій і підтримки.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T110-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Записи архітектурних рішень (ADR)`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Команда записує, чому обрала модульний моноліт і PostgreSQL для бронювань, погодившись на спільне розгортання заради простіших транзакцій і підтримки.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var r={slug:i,topicId:110,questions:n};export{r as default,n as questions,i as slug,o as topicId};